CREATE TABLE IF NOT EXISTS app_sequence (name VARCHAR(60) PRIMARY KEY, last_value BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS user_account (id BIGINT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, email VARCHAR(160) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(30) NOT NULL DEFAULT 'USER', created_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS career_profile (user_id BIGINT PRIMARY KEY, school VARCHAR(120), major VARCHAR(120), grade VARCHAR(30), target_position VARCHAR(120), target_city VARCHAR(80), self_description TEXT, CONSTRAINT fk_profile_user FOREIGN KEY (user_id) REFERENCES user_account(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS skill (id BIGINT PRIMARY KEY, code VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, category VARCHAR(40) NOT NULL, aliases_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_skill (id BIGINT PRIMARY KEY, user_id BIGINT NOT NULL, skill_id BIGINT NOT NULL, level SMALLINT NOT NULL, source VARCHAR(30) NOT NULL, evidence TEXT, source_ref_id BIGINT, confirmed BOOLEAN NOT NULL, CONSTRAINT fk_user_skill_user FOREIGN KEY (user_id) REFERENCES user_account(id) ON DELETE CASCADE, CONSTRAINT fk_user_skill_skill FOREIGN KEY (skill_id) REFERENCES skill(id));
CREATE INDEX IF NOT EXISTS idx_user_skill_user ON user_skill(user_id);
CREATE TABLE IF NOT EXISTS resume (id BIGINT PRIMARY KEY, user_id BIGINT NOT NULL, file_name VARCHAR(255) NOT NULL, content_type VARCHAR(100), file_key VARCHAR(500), raw_text TEXT, parsed_json TEXT, status VARCHAR(30) NOT NULL, is_current BOOLEAN NOT NULL, error_message VARCHAR(500), created_at TIMESTAMP NOT NULL, CONSTRAINT fk_resume_user FOREIGN KEY (user_id) REFERENCES user_account(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_resume_user ON resume(user_id);
CREATE TABLE IF NOT EXISTS job_description (id BIGINT PRIMARY KEY, user_id BIGINT NOT NULL, company_name VARCHAR(160), position_name VARCHAR(160) NOT NULL, raw_content TEXT NOT NULL, requirements_json TEXT NOT NULL, status VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL, CONSTRAINT fk_job_user FOREIGN KEY (user_id) REFERENCES user_account(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_job_user ON job_description(user_id);
CREATE TABLE IF NOT EXISTS conversation (id BIGINT PRIMARY KEY, user_id BIGINT NOT NULL, scene VARCHAR(30) NOT NULL, title VARCHAR(160), job_id BIGINT, created_at TIMESTAMP NOT NULL, CONSTRAINT fk_conversation_user FOREIGN KEY (user_id) REFERENCES user_account(id) ON DELETE CASCADE, CONSTRAINT fk_conversation_job FOREIGN KEY (job_id) REFERENCES job_description(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS message (id BIGINT PRIMARY KEY, conversation_id BIGINT NOT NULL, role VARCHAR(20) NOT NULL, content TEXT NOT NULL, metadata_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL, CONSTRAINT fk_message_conversation FOREIGN KEY (conversation_id) REFERENCES conversation(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS knowledge_chunk (id BIGINT PRIMARY KEY, title VARCHAR(255) NOT NULL, source VARCHAR(500), topic VARCHAR(120), section VARCHAR(255), content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS interview (id BIGINT PRIMARY KEY, user_id BIGINT NOT NULL, job_id BIGINT NOT NULL, status VARCHAR(30) NOT NULL, question_ids_json TEXT NOT NULL, total_score DOUBLE PRECISION, report_json TEXT, started_at TIMESTAMP, finished_at TIMESTAMP, CONSTRAINT fk_interview_user FOREIGN KEY (user_id) REFERENCES user_account(id) ON DELETE CASCADE, CONSTRAINT fk_interview_job FOREIGN KEY (job_id) REFERENCES job_description(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS interview_question (id BIGINT PRIMARY KEY, interview_id BIGINT NOT NULL, sequence_no INTEGER NOT NULL, question TEXT NOT NULL, skill_name VARCHAR(120), difficulty VARCHAR(20) NOT NULL, reference_points_json TEXT NOT NULL, user_answer TEXT, score DOUBLE PRECISION, evaluation_json TEXT, parent_question_id BIGINT, CONSTRAINT fk_question_interview FOREIGN KEY (interview_id) REFERENCES interview(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_question_interview ON interview_question(interview_id, sequence_no);
